const int char_code = 0x35;
const float lwidth = 0.2;
const int n_cols = 16;

// Char Coords are the coordinates within the character from [0, 1]
// Return the texture coordinates
vec2 texCoords(int ascii_code, vec2 charCoords)
{
    vec2 tile = vec2(ascii_code%n_cols, ascii_code/n_cols);
    vec2 charCoordsV = vec2(charCoords.x, 1.0-charCoords.y);
    vec2 tile_coords = (tile + charCoordsV) * (iChannelResolution[0].xy)/float(n_cols); 

    return tile_coords;
}

vec2 d2edge(vec4 texvalue, vec2 tex_coord, vec2 pix_coord)
{
    // project the vector from tex_coord to pix_coord along the gradient
    // of the distance and subtract the distance value
    vec2 derivative = texvalue.tp;
    float nearest_distance = (texvalue.q - 0.5)*255.0/4.0;

    vec2 dist_orig = pix_coord - vec2(tex_coord);
    float dist_projected = dot(dist_orig, (derivative - 0.5)*2.0);
    float dist_perp = dot(dist_orig, (derivative.yx - 0.5)*vec2(1.0,-1.0)*2.0);
    return vec2(dist_projected + nearest_distance,
                dist_perp);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.y;
    vec2 uvMouse = iMouse.xy/iResolution.y;
    vec2 exact_coords = texCoords(char_code, uv);

    vec2 mouseSample = texCoords(char_code, uvMouse);

    vec4 sdf_mouse = texture(iChannel0, mouseSample/iChannelResolution[0].xy);

    vec2 dnear = d2edge(sdf_mouse, mouseSample, exact_coords);
    vec2 edge_mask = 1.0 - step(-lwidth, dnear) + step(lwidth, dnear);

    float fnt = texture(iChannel0, exact_coords/iChannelResolution[0].xy).x;
    fragColor = vec4(vec3(fnt, 1.0-edge_mask.y, 1.0-fnt)*edge_mask.x, 1.0);
}
